import { Component } from '@angular/core';
import { AuthService } from '../../services/auth.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent {
  user = { email: '', password: '' };

  constructor(private auth: AuthService, private router: Router) {}

  onLogin() {
    this.auth.login(this.user).subscribe({
      next: (res) => {
        console.log('Login Response:', res); // Debug response

        if (res.message) {
          alert(res.message);
        }

        // Assuming backend returns { role: 'admin' } or { role: 'customer' }
        if (res.role === 'admin') {
          this.router.navigate(['/admin/dashboard']);
        } else if (res.role === 'customer') {
          this.router.navigate(['/customer/home']);
        } else {
          this.router.navigate(['/']);
        }
      },
      error: (err) => {
        console.error('Login error:', err);
        alert('Invalid credentials');
      }
    });
  }
}
<div class="d-flex justify-content-center align-items-center vh-100 bg-light">
  <div class="card p-4 shadow-lg rounded-4" style="width: 24rem;">
    <h4 class="text-center mb-4 fw-bold text-primary">Login</h4>

    <form #loginForm="ngForm" (ngSubmit)="onLogin()">
      <div class="mb-3">
        <label for="email" class="form-label">Email</label>
        <input
          type="email"
          id="email"
          class="form-control shadow-sm"
          name="email"
          required
          [(ngModel)]="user.email"
        />
      </div>

      <div class="mb-3">
        <label for="password" class="form-label">Password</label>
        <input
          type="password"
          id="password"
          class="form-control shadow-sm"
          name="password"
          required
          [(ngModel)]="user.password"
        />
      </div>

      <button type="submit" class="btn btn-primary w-100 shadow-sm">Login</button>

      <div class="text-end mt-2">
        <a routerLink="/forgot-password" class="text-decoration-none">Forgot Password?</a>
      </div>
    </form>
  </div>
</div>
